import { Hono } from "hono@4";import {gunzipSync} from "node:zlib";
import { readFileSync } from "node:fs";
const app=new Hono();
const P="/data/";
function txt(name){return readFileSync(P+name,"utf8")}
function bytes(name){return readFileSync(P+name)}
const UPGRADE_PATCH="\n{const i=tools.findIndex(t=>t.r==='data');if(i>1){const x=tools.splice(i,1)[0];tools.splice(1,0,x)}}\nfunction upgradeStages(){\n  const out=[];\n  for(let t=1;t<=6;t++)out.push({id:'T'+t,label:'T'+t+' '+(DATA.codex.tiers[String(t)]?.name||''),tier:t,rank:null});\n  for(let r=1;r<=30;r++)out.push({id:'A'+r,label:'A'+r+' Awakened',tier:null,rank:r});\n  return out;\n}\nfunction upgradeStageMax(s){return s.tier?Number(DATA.codex.tiers[String(s.tier)]?.max_level||0):30}\nfunction upgradeStageRows(s){return s.tier?(DATA.codex.tiers[String(s.tier)]?.rows||[]):(DATA.codex.awaken?.rows?.[String(s.rank)]||[])}\nfunction upgradeMaterialName(slug){return DATA.materials.find(m=>m.slug===slug)?.name||human(slug)}\nfunction upgradeStageOptions(selected){return upgradeStages().map(s=>'<option value=\"'+s.id+'\" '+(s.id===selected?'selected':'')+'>'+s.label+'</option>').join('')}\nfunction upgradeLevelOptions(stageId,selected){\n  const s=upgradeStages().find(x=>x.id===stageId)||upgradeStages()[0],max=upgradeStageMax(s);\n  return Array.from({length:max+1},(_,i)=>'<option value=\"'+i+'\" '+(Number(selected)===i?'selected':'')+'>+'+i+'</option>').join('')\n}\nfunction upgradeAddMat(map,slug,qty){if(!slug)return;map[slug]=(map[slug]||0n)+BigInt(qty||0)}\nfunction calculateItemUpgrade(currentId,currentLevel,targetId,targetLevel){\n  const list=upgradeStages(),ci=list.findIndex(s=>s.id===currentId),ti=list.findIndex(s=>s.id===targetId);\n  currentLevel=Math.max(0,Number(currentLevel)||0);targetLevel=Math.max(0,Number(targetLevel)||0);\n  if(ci<0||ti<0||ti<ci||(ci===ti&&targetLevel<currentLevel))return {valid:false,message:'Target must be at or after your current progression.'};\n  let gold=0n,mats={},steps=0,idx=ci,level=currentLevel;\n  const addRow=row=>{\n    gold+=BigInt(row?.gold||0);\n    upgradeAddMat(mats,row?.fragment_slug,row?.fragments);\n    Object.entries(row?.monster_materials||{}).forEach(([k,v])=>upgradeAddMat(mats,k,v));\n    if(Array.isArray(row?.extra_materials))row.extra_materials.forEach(x=>upgradeAddMat(mats,x.slug,x.quantity));\n    else Object.entries(row?.extra_materials||{}).forEach(([k,v])=>upgradeAddMat(mats,k,v));\n    steps++;\n  };\n  const addTransition=(from,to)=>{\n    if(from.tier&&from.tier<6){\n      const p=DATA.codex.tier_upgrades.find(x=>Number(x.from_tier)===from.tier);\n      if(!p)throw new Error('Missing tier transition '+from.id);\n      gold+=BigInt(p.gold||0);\n      upgradeAddMat(mats,p.essence?.slug,p.essence?.quantity);\n      Object.entries(p.monster_materials||{}).forEach(([k,v])=>upgradeAddMat(mats,k,v));\n    }else{\n      const rank=from.tier===6?1:to.rank;\n      const t=DATA.codex.awaken.transitions.find(x=>Number(x.rank)===rank);\n      if(!t)throw new Error('Missing Awaken transition A'+rank);\n      gold+=BigInt(t.gold||0);\n      (t.materials||[]).forEach(x=>upgradeAddMat(mats,x.slug,x.quantity));\n    }\n    steps++;\n  };\n  try{\n    while(idx<ti){\n      const s=list[idx],rows=upgradeStageRows(s),max=upgradeStageMax(s);\n      while(level<max){\n        const row=rows.find(r=>Number(r.current)===level);\n        if(!row)return {valid:false,message:'Missing configured row for '+s.id+' +'+level+'.'};\n        addRow(row);level++;\n      }\n      addTransition(s,list[idx+1]);idx++;level=0;\n    }\n    const s=list[ti],rows=upgradeStageRows(s);\n    while(level<targetLevel){\n      const row=rows.find(r=>Number(r.current)===level);\n      if(!row)return {valid:false,message:'Missing configured row for '+s.id+' +'+level+'.'};\n      addRow(row);level++;\n    }\n  }catch(e){return {valid:false,message:String(e.message||e)}}\n  return {valid:true,gold,mats,steps};\n}\nfunction nextItemUpgrade(stageId,level){\n  const list=upgradeStages(),i=list.findIndex(s=>s.id===stageId);if(i<0)return null;\n  const s=list[i],max=upgradeStageMax(s);\n  if(Number(level)<max)return {stageId:s.id,level:Number(level)+1,label:s.id+' +'+(Number(level)+1)};\n  if(i<list.length-1)return {stageId:list[i+1].id,level:0,label:list[i+1].id+' +0'};\n  return null;\n}\nfunction upgradeCostHtml(title,result,label){\n  if(!result?.valid)return '<div class=\"category-card\"><h3>'+title+'</h3><div class=\"empty\">'+(result?.message||'No route available.')+'</div></div>';\n  const mats=Object.entries(result.mats).filter(([,q])=>q>0n).sort((a,b)=>upgradeMaterialName(a[0]).localeCompare(upgradeMaterialName(b[0])));\n  return '<div class=\"category-card\">'+\n    '<div class=\"row between wrap\"><div><h3>'+title+'</h3><p style=\"font-size:10px\">'+label+'</p></div><span class=\"pill accent\">'+result.steps+' step'+(result.steps===1?'':'s')+'</span></div>'+\n    '<div class=\"twocol\" style=\"margin-top:10px\">'+\n      '<div class=\"metric\"><small>Gold</small><strong class=\"gold\">'+result.gold.toLocaleString()+'</strong></div>'+\n      '<div class=\"metric\"><small>Material types</small><strong>'+mats.length+'</strong></div>'+\n    '</div>'+\n    (mats.length?'<div class=\"card-list\" style=\"margin-top:10px\">'+mats.map(([slug,qty])=>\n      '<div class=\"list-card\">'+officialArt('items/materials/'+slug+'.webp','material:'+slug,36)+\n      '<div class=\"list-main\"><div class=\"list-title\">'+upgradeMaterialName(slug)+'</div><div class=\"list-meta\">'+slug+'</div></div><strong>'+qty.toLocaleString()+'</strong></div>'\n    ).join('')+'</div>':'<div class=\"note\" style=\"margin-top:10px\">No materials required for this step.</div>')+\n  '</div>';\n}\nfunction renderData(){\n  state.upgrade=state.upgrade||{currentStage:'T1',currentLevel:0,targetStage:'T6',targetLevel:30};\n  const u=state.upgrade,stages=upgradeStages();\n  if(!stages.some(x=>x.id===u.currentStage))u.currentStage='T1';\n  if(!stages.some(x=>x.id===u.targetStage))u.targetStage='T6';\n  u.currentLevel=Math.min(Number(u.currentLevel)||0,upgradeStageMax(stages.find(x=>x.id===u.currentStage)));\n  u.targetLevel=Math.min(Number(u.targetLevel)||0,upgradeStageMax(stages.find(x=>x.id===u.targetStage)));\n  $('#dataPage').innerHTML=\n    '<div class=\"panel game glow\">'+\n      '<div class=\"row between wrap\"><div><h3>Item Upgrade Calculator</h3><p style=\"font-size:10px\">See exactly what the next upgrade costs, or total everything from your current gear to any target through A30.</p></div><span class=\"pill good\">T1 → A30</span></div>'+\n      '<div class=\"config-grid\" style=\"margin-top:12px\">'+\n        '<label>Current stage<select id=\"upCurrentStage\">'+upgradeStageOptions(u.currentStage)+'</select></label>'+\n        '<label>Current level<select id=\"upCurrentLevel\">'+upgradeLevelOptions(u.currentStage,u.currentLevel)+'</select></label>'+\n        '<label>Target stage<select id=\"upTargetStage\">'+upgradeStageOptions(u.targetStage)+'</select></label>'+\n        '<label>Target level<select id=\"upTargetLevel\">'+upgradeLevelOptions(u.targetStage,u.targetLevel)+'</select></label>'+\n      '</div>'+\n      '<div class=\"row wrap\" style=\"margin-top:10px\">'+\n        '<button class=\"secondary\" id=\"upTargetNext\">Target next upgrade</button>'+\n        '<button class=\"secondary\" id=\"upTargetStageMax\">Target stage max</button>'+\n        '<button class=\"ghost\" id=\"upTargetA30\">Target A30 +30</button>'+\n      '</div>'+\n      '<div class=\"note\" style=\"margin-top:10px\">Uses the verified configured upgrade rows and promotion costs. Failed upgrade attempts are not included.</div>'+\n    '</div>'+\n    '<div id=\"upNextResult\" class=\"panel\"></div>'+\n    '<div id=\"upTargetResult\" class=\"panel\"></div>'+\n    '<div class=\"panel\"><div class=\"row between wrap\"><div><h3>Related tools</h3><p style=\"font-size:10px\">Item details, Drop Bonuses and comparison stay in the Codex.</p></div><button class=\"secondary\" data-route=\"codex\">Open Gear Codex</button></div></div>';\n  const refreshLevels=(stageEl,levelEl)=>{\n    const s=upgradeStages().find(x=>x.id===stageEl.value);\n    const v=Math.min(Number(levelEl.value)||0,upgradeStageMax(s));\n    levelEl.innerHTML=upgradeLevelOptions(stageEl.value,v);\n  };\n  const sync=()=>{\n    u.currentStage=$('#upCurrentStage').value;u.currentLevel=Number($('#upCurrentLevel').value)||0;\n    u.targetStage=$('#upTargetStage').value;u.targetLevel=Number($('#upTargetLevel').value)||0;save();\n    const next=nextItemUpgrade(u.currentStage,u.currentLevel);\n    $('#upNextResult').innerHTML=next\n      ?upgradeCostHtml('Next upgrade',calculateItemUpgrade(u.currentStage,u.currentLevel,next.stageId,next.level),u.currentStage+' +'+u.currentLevel+' → '+next.label)\n      :'<div class=\"category-card\"><h3>Next upgrade</h3><div class=\"empty\">A30 +30 is fully maxed.</div></div>';\n    $('#upTargetResult').innerHTML=upgradeCostHtml('Target total',calculateItemUpgrade(u.currentStage,u.currentLevel,u.targetStage,u.targetLevel),u.currentStage+' +'+u.currentLevel+' → '+u.targetStage+' +'+u.targetLevel);\n  };\n  $('#upCurrentStage').onchange=()=>{refreshLevels($('#upCurrentStage'),$('#upCurrentLevel'));sync()};\n  $('#upCurrentLevel').onchange=sync;\n  $('#upTargetStage').onchange=()=>{refreshLevels($('#upTargetStage'),$('#upTargetLevel'));sync()};\n  $('#upTargetLevel').onchange=sync;\n  $('#upTargetNext').onclick=()=>{const n=nextItemUpgrade($('#upCurrentStage').value,Number($('#upCurrentLevel').value)||0);if(!n)return;$('#upTargetStage').value=n.stageId;refreshLevels($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value=String(n.level);sync()};\n  $('#upTargetStageMax').onclick=()=>{const s=upgradeStages().find(x=>x.id===$('#upTargetStage').value);$('#upTargetLevel').value=String(upgradeStageMax(s));sync()};\n  $('#upTargetA30').onclick=()=>{$('#upTargetStage').value='A30';refreshLevels($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value='30';sync()};\n  sync();\n}\n";
const PERM_PATCH="\nconst PERM_GEAR_TRACK_MAX=50;\nfunction permPow(b,e){let x=1n,n=BigInt(e);while(n>0n){if(n&1n)x*=b;b*=b;n>>=1n}return x}\nfunction permRoundDiv(n,d){return (2n*n+d)/(2n*d)}\nfunction permCeilDiv(n,d){return (n+d-1n)/d}\nfunction permExtraMats(rank){\n if(rank>=10)return [{slug:'abyssal-ember',quantity:3},{slug:'eternal-sigil',quantity:2}];\n if(rank>=5)return [{slug:'abyssal-ember',quantity:2},{slug:'eternal-sigil',quantity:1}];\n if(rank>=3)return [{slug:'abyssal-ember',quantity:2}];\n return [{slug:'abyssal-ember',quantity:1}];\n}\nfunction permAwakenRow(rank,current){\n const published=DATA.codex.awaken?.rows?.[String(rank)]||[];\n const exact=published.find(r=>Number(r.current)===Number(current));\n if(exact)return exact;\n if(rank<=30)return null;\n const base=(DATA.codex.tiers?.['6']?.rows||[]).find(r=>Number(r.current)===Number(current));\n if(!base)return null;\n const e=rank;\n const gold=permRoundDiv(BigInt(base.gold||0)*10n*permPow(5n,e),permPow(2n,e));\n const fn=BigInt(base.fragments||0)*permPow(3n,4)*permPow(5n,rank-4);\n const fd=permPow(2n,4)*permPow(4n,rank-4);\n const fragments=permCeilDiv(fn,fd);\n return {rank,current:Number(current),target:Number(current)+1,gold:String(gold),fragment_slug:'infernal-fragment',fragments:String(fragments),monster_materials:{},extra_materials:permExtraMats(rank),fail:Number(base.fail||0),success:Number(base.success??(1-Number(base.fail||0))),post30:true,unknown_monster_materials:true};\n}\nfunction permTransition(rank){\n const exact=(DATA.codex.awaken?.transitions||[]).find(x=>Number(x.rank)===Number(rank));\n if(exact)return exact;\n if(rank<=30)return null;\n return {rank,gold:String(50000000n*permPow(2n,rank-1)),materials:[{slug:'primeval-core',quantity:8},{slug:'tyrants-crown',quantity:20}],failure:0,post30:true};\n}\nupgradeStages=function(){\n const out=[];\n for(let t=1;t<=6;t++)out.push({id:'T'+t,label:'T'+t+' '+(DATA.codex.tiers[String(t)]?.name||''),tier:t,rank:null});\n for(let r=1;r<=PERM_GEAR_TRACK_MAX;r++)out.push({id:'A'+r,label:'A'+r+' Awakened',tier:null,rank:r});\n return out;\n};\nupgradeStageRows=function(s){\n if(s.tier)return DATA.codex.tiers[String(s.tier)]?.rows||[];\n if(s.rank<=30)return DATA.codex.awaken?.rows?.[String(s.rank)]||[];\n return Array.from({length:30},(_,i)=>permAwakenRow(s.rank,i)).filter(Boolean);\n};\ncalculateItemUpgrade=function(currentId,currentLevel,targetId,targetLevel){\n const list=upgradeStages(),ci=list.findIndex(s=>s.id===currentId),ti=list.findIndex(s=>s.id===targetId);\n currentLevel=Math.max(0,Number(currentLevel)||0);targetLevel=Math.max(0,Number(targetLevel)||0);\n if(ci<0||ti<0||ti<ci||(ci===ti&&targetLevel<currentLevel))return {valid:false,message:'Target must be at or after your current progression.'};\n let gold=0n,mats={},steps=0,idx=ci,level=currentLevel,partial=false,post30Rows=0;\n const addRow=row=>{gold+=BigInt(row?.gold||0);upgradeAddMat(mats,row?.fragment_slug,row?.fragments);Object.entries(row?.monster_materials||{}).forEach(([k,v])=>upgradeAddMat(mats,k,v));if(Array.isArray(row?.extra_materials))row.extra_materials.forEach(x=>upgradeAddMat(mats,x.slug,x.quantity));else Object.entries(row?.extra_materials||{}).forEach(([k,v])=>upgradeAddMat(mats,k,v));if(row?.unknown_monster_materials){partial=true;post30Rows++}steps++};\n const addTransition=(from,to)=>{\n   if(from.tier&&from.tier<6){const p=DATA.codex.tier_upgrades.find(x=>Number(x.from_tier)===from.tier);if(!p)throw new Error('Missing tier transition '+from.id);gold+=BigInt(p.gold||0);upgradeAddMat(mats,p.essence?.slug,p.essence?.quantity);Object.entries(p.monster_materials||{}).forEach(([k,v])=>upgradeAddMat(mats,k,v))}\n   else{const rank=from.tier===6?1:to.rank,t=permTransition(rank);if(!t)throw new Error('Missing Awaken transition A'+rank);gold+=BigInt(t.gold||0);(t.materials||[]).forEach(x=>upgradeAddMat(mats,x.slug,x.quantity))}\n   steps++;\n };\n try{\n   while(idx<ti){const s=list[idx],rows=upgradeStageRows(s),max=upgradeStageMax(s);while(level<max){const row=rows.find(r=>Number(r.current)===level);if(!row)return {valid:false,message:'Missing configured row for '+s.id+' +'+level+'.'};addRow(row);level++}addTransition(s,list[idx+1]);idx++;level=0}\n   const s=list[ti],rows=upgradeStageRows(s);while(level<targetLevel){const row=rows.find(r=>Number(r.current)===level);if(!row)return {valid:false,message:'Missing configured row for '+s.id+' +'+level+'.'};addRow(row);level++}\n }catch(e){return {valid:false,message:String(e.message||e)}}\n return {valid:true,gold,mats,steps,partial,post30Rows};\n};\nupgradeCostHtml=function(title,result,label){\n if(!result?.valid)return '<div class=\"category-card\"><h3>'+title+'</h3><div class=\"empty\">'+(result?.message||'No route available.')+'</div></div>';\n const mats=Object.entries(result.mats).filter(([,q])=>q>0n).sort((a,b)=>upgradeMaterialName(a[0]).localeCompare(upgradeMaterialName(b[0])));\n return '<div class=\"category-card\"><div class=\"row between wrap\"><div><h3>'+title+'</h3><p style=\"font-size:10px\">'+label+'</p></div><span class=\"pill '+(result.partial?'gold':'accent')+'\">'+result.steps+' step'+(result.steps===1?'':'s')+'</span></div><div class=\"twocol\" style=\"margin-top:10px\"><div class=\"metric\"><small>Gold</small><strong class=\"gold\">'+result.gold.toLocaleString()+'</strong></div><div class=\"metric\"><small>Known material types</small><strong>'+mats.length+'</strong></div></div>'+(result.partial?'<div class=\"note\" style=\"margin-top:10px\"><b>Post-A30 permanent progression:</b> Gold, Infernal Fragments, rare per-level materials and Awakening rank-up costs use the continuing live formulas. The public config currently publishes ordinary monster-material recipes only through A30, so those ordinary materials are deliberately not guessed for '+result.post30Rows+' post-A30 enhancement step'+(result.post30Rows===1?'':'s')+'.</div>':'')+(mats.length?'<div class=\"card-list\" style=\"margin-top:10px\">'+mats.map(([slug,qty])=>'<div class=\"list-card\">'+officialArt('items/materials/'+slug+'.webp','material:'+slug,36)+'<div class=\"list-main\"><div class=\"list-title\">'+upgradeMaterialName(slug)+'</div><div class=\"list-meta\">'+slug+'</div></div><strong>'+qty.toLocaleString()+'</strong></div>').join('')+'</div>':'<div class=\"note\" style=\"margin-top:10px\">No known materials required for this step.</div>')+'</div>';\n};\nupgradeSnapshot=function(tier,level,awaken=0){\n const aRank=Math.max(0,Math.min(PERM_GEAR_TRACK_MAX,Number(awaken)||0));\n if(aRank){\n   const l=Math.max(0,Math.min(30,Number(level)||0));\n   if(l<30){\n     const row=permAwakenRow(aRank,l);if(!row)return '<div class=\"note\">No upgrade data found for A'+aRank+' +'+l+'.</div>';\n     const success=Number(row.success??(1-Number(row.fail||0)))*100,fragName=DATA.codex.tiers?.['6']?.fragment_name||'Infernal Fragment';\n     return '<div class=\"category-card\"><div class=\"row between\"><div><h3>Awakened Upgrade • A'+aRank+' +'+l+' → +'+(l+1)+'</h3><p style=\"font-size:9px\">'+money(row.gold)+' Gold • '+fmt(success,1)+'% success</p></div><div class=\"req-runes\">'+(row.post30?'':gtag(row.monster_materials))+'<span class=\"pill accent\">'+row.fragments+' '+fragName+'</span></div></div>'+awakenRowMaterials(row)+(row.unknown_monster_materials?'<div class=\"note\" style=\"margin-top:8px\">Post-A30 ordinary monster-material quantities are not published in the current config, so Arcana does not invent them.</div>':'')+'</div>';\n   }\n   if(aRank<PERM_GEAR_TRACK_MAX){const tr=permTransition(aRank+1);return tr?'<div class=\"category-card\"><div class=\"row between\"><div><h3>Awaken Rank Up • A'+aRank+' → A'+(aRank+1)+'</h3><p style=\"font-size:9px\">'+money(tr.gold)+' Gold • 100% success</p></div><div class=\"req-runes\">'+gtag(tr.materials)+'<span class=\"pill accent\">A'+(aRank+1)+'</span></div></div><div class=\"material-costs\">'+(tr.materials||[]).map(m=>costChip(m.slug,m.quantity)).join('')+'</div></div>':''}\n   return '<div class=\"category-card\"><div class=\"row between\"><div><h3>Arcana tracking limit</h3><p style=\"font-size:9px\">A50 +30 is the current Companion display limit, not a confirmed game cap.</p></div><span class=\"pill gold\">A50</span></div></div>';\n }\n const t=DATA.codex.tiers[String(tier)],l=Math.max(0,Math.min(Number(level)||0,t.max_level));\n if(l<t.max_level){const row=t.rows.find(r=>r.current===l);if(!row)return'';return '<div class=\"category-card\"><div class=\"row between\"><div><h3>Next Upgrade • +'+l+' → +'+(l+1)+'</h3><p style=\"font-size:9px\">'+money(row.gold)+' Gold • '+fmt((1-row.fail)*100,1)+'% success</p></div><div class=\"req-runes\">'+gtag(row.monster_materials)+'<span class=\"pill\">'+row.fragments+' '+t.fragment_name+'</span></div></div>'+materialChips(row.monster_materials)+'</div>'}\n if(tier<6){const u=DATA.codex.tier_upgrades.find(r=>r.from_tier===tier);return '<div class=\"category-card\"><div class=\"row between\"><div><h3>Tier Up • T'+tier+' → T'+(tier+1)+'</h3><p style=\"font-size:9px\">'+money(u.gold)+' Gold • '+fmt((1-u.failure)*100,1)+'% success</p></div><div class=\"req-runes\">'+gtag(u.monster_materials)+'<span class=\"pill gold\">'+u.essence.quantity+' '+u.essence.name+'</span></div></div>'+materialChips(u.monster_materials)+'</div>'}\n const tr=permTransition(1);return tr?'<div class=\"category-card\"><div class=\"row between\"><div><h3>Awaken Rank Up • T6 → A1</h3><p style=\"font-size:9px\">'+money(tr.gold)+' Gold • 100% success</p></div><div class=\"req-runes\">'+gtag(tr.materials)+'<span class=\"pill accent\">A1</span></div></div><div class=\"material-costs\">'+(tr.materials||[]).map(m=>costChip(m.slug,m.quantity)).join('')+'</div></div>':'';\n};\nconst permOldBiomePlan=biomePlan;\ngateLadder=function(){let out=[],s=1,g=rankGate(1);for(let a=2;a<=31;a++){let n=a<=30?rankGate(a):-1;if(n!==g){out.push([s,a-1,g]);s=a;g=n}}return out.map(([a,b,t])=>'<span class=\"pill\">A'+a+(b>a?'–A'+b:'')+' • T'+t+'</span>').join('')};\nbiomePlan=function(t,l,a){\n if(Number(a)>30)return '<div class=\"category-card\" style=\"margin-top:10px\"><div class=\"row between\"><div><h3>Biome Upgrade Gate</h3><p style=\"font-size:9px\">Post-A30 standard monster-material recipes are not published in the current config.</p></div><span class=\"pill gold\">Permanent</span></div><div class=\"note\" style=\"margin-top:9px\">Arcana will not claim a biome requirement until the post-A30 monster-material recipe is verified.</div></div>';\n return permOldBiomePlan(t,l,a).replaceAll('A50 +30','A30 +30').replace('every verified upgrade through A30 +30','every published monster-material recipe through A30 +30');\n};\nrenderData=function(){\n state.upgrade=state.upgrade||{currentStage:'T1',currentLevel:0,targetStage:'T6',targetLevel:30};\n const u=state.upgrade,stages=upgradeStages();\n if(!stages.some(x=>x.id===u.currentStage))u.currentStage='T1';if(!stages.some(x=>x.id===u.targetStage))u.targetStage='T6';\n u.currentLevel=Math.min(Number(u.currentLevel)||0,upgradeStageMax(stages.find(x=>x.id===u.currentStage)));u.targetLevel=Math.min(Number(u.targetLevel)||0,upgradeStageMax(stages.find(x=>x.id===u.targetStage)));\n $('#dataPage').innerHTML='<div class=\"panel game glow\"><div class=\"row between wrap\"><div><h3>Item Upgrade Calculator</h3><p style=\"font-size:10px\">Seasonal and Permanent progression from T1 through Arcana’s current A50 tracking range.</p></div><span class=\"pill good\">T1 → A50</span></div><div class=\"config-grid\" style=\"margin-top:12px\"><label>Current stage<select id=\"upCurrentStage\">'+upgradeStageOptions(u.currentStage)+'</select></label><label>Current level<select id=\"upCurrentLevel\">'+upgradeLevelOptions(u.currentStage,u.currentLevel)+'</select></label><label>Target stage<select id=\"upTargetStage\">'+upgradeStageOptions(u.targetStage)+'</select></label><label>Target level<select id=\"upTargetLevel\">'+upgradeLevelOptions(u.targetStage,u.targetLevel)+'</select></label></div><div class=\"row wrap\" style=\"margin-top:10px\"><button class=\"secondary\" id=\"upTargetNext\">Target next upgrade</button><button class=\"secondary\" id=\"upTargetStageMax\">Target stage max</button><button class=\"ghost\" id=\"upTargetA50\">Target A50 +30</button></div><div class=\"note\" style=\"margin-top:10px\">A1–A30 uses published rows. A31–A50 uses the configured continuing Gold, Infernal Fragment, rare-material and rank-up formulas. Ordinary post-A30 monster-material quantities are left unguessed.</div></div><div id=\"upNextResult\" class=\"panel\"></div><div id=\"upTargetResult\" class=\"panel\"></div><div class=\"panel\"><div class=\"row between wrap\"><div><h3>Related tools</h3><p style=\"font-size:10px\">Item details, Drop Bonuses and comparison stay in the Codex.</p></div><button class=\"secondary\" data-route=\"codex\">Open Gear Codex</button></div></div>';\n const refresh=(s,l)=>{const st=upgradeStages().find(x=>x.id===s.value),v=Math.min(Number(l.value)||0,upgradeStageMax(st));l.innerHTML=upgradeLevelOptions(s.value,v)};\n const sync=()=>{u.currentStage=$('#upCurrentStage').value;u.currentLevel=Number($('#upCurrentLevel').value)||0;u.targetStage=$('#upTargetStage').value;u.targetLevel=Number($('#upTargetLevel').value)||0;save();const n=nextItemUpgrade(u.currentStage,u.currentLevel);$('#upNextResult').innerHTML=n?upgradeCostHtml('Next upgrade',calculateItemUpgrade(u.currentStage,u.currentLevel,n.stageId,n.level),u.currentStage+' +'+u.currentLevel+' → '+n.label):'<div class=\"category-card\"><h3>Tracking limit reached</h3><div class=\"empty\">A50 +30 is Arcana’s current display limit, not a confirmed game cap.</div></div>';$('#upTargetResult').innerHTML=upgradeCostHtml('Target total',calculateItemUpgrade(u.currentStage,u.currentLevel,u.targetStage,u.targetLevel),u.currentStage+' +'+u.currentLevel+' → '+u.targetStage+' +'+u.targetLevel)};\n $('#upCurrentStage').onchange=()=>{refresh($('#upCurrentStage'),$('#upCurrentLevel'));sync()};$('#upCurrentLevel').onchange=sync;$('#upTargetStage').onchange=()=>{refresh($('#upTargetStage'),$('#upTargetLevel'));sync()};$('#upTargetLevel').onchange=sync;\n $('#upTargetNext').onclick=()=>{const n=nextItemUpgrade($('#upCurrentStage').value,Number($('#upCurrentLevel').value)||0);if(!n)return;$('#upTargetStage').value=n.stageId;refresh($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value=String(n.level);sync()};\n $('#upTargetStageMax').onclick=()=>{const s=upgradeStages().find(x=>x.id===$('#upTargetStage').value);$('#upTargetLevel').value=String(upgradeStageMax(s));sync()};\n $('#upTargetA50').onclick=()=>{$('#upTargetStage').value='A50';refresh($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value='30';sync()};sync();\n};\n";

// ARCANA_UPGRADE_PREFARM_BEGIN
const UPGRADE_PREFARM_PATCH="\nconst UPGRADE_FAILURE_REFUND=0.30;\nconst UPGRADE_SCALE=1000000n;\nfunction upgradeScaledCeil(n){return (n+UPGRADE_SCALE-1n)/UPGRADE_SCALE}\nfunction upgradeAddScaled(map,slug,qty,factor){\n  if(!slug||qty==null)return;\n  const q=BigInt(qty||0);\n  map[slug]=(map[slug]||0n)+q*factor;\n}\nfunction upgradeFailInfo(x){\n  const fail=Math.max(0,Math.min(.999999,Number(x?.fail??x?.failure??0)||0));\n  const success=Math.max(.000001,Math.min(1,Number(x?.success??(1-fail))||1));\n  return {fail,success};\n}\nfunction upgradeCostFactors(x,includeFailures){\n  if(!includeFailures)return {gold:UPGRADE_SCALE,materials:UPGRADE_SCALE,fail:0,success:1};\n  const {fail,success}=upgradeFailInfo(x);\n  if(fail<=0)return {gold:UPGRADE_SCALE,materials:UPGRADE_SCALE,fail,success};\n  const attempts=1/success;\n  const failures=fail/success;\n  const materialMultiplier=1+failures*(1-UPGRADE_FAILURE_REFUND);\n  return {\n    gold:BigInt(Math.round(attempts*1e6)),\n    materials:BigInt(Math.round(materialMultiplier*1e6)),\n    fail,success\n  };\n}\nfunction upgradeBiomeInfo(slug){\n  const tier=(typeof BT!=='undefined'&&BT)?Number(BT[slug]||0):0;\n  if(tier){\n    const name=(typeof BN!=='undefined'&&BN&&BN[tier])?BN[tier]:('Biome T'+tier);\n    return {tier,name,label:'Biome T'+tier+' • '+name,key:'b'+String(tier).padStart(2,'0')};\n  }\n  const m=DATA.materials.find(x=>x.slug===slug);\n  const kind=m?.type?human(m.type):'Special material';\n  return {tier:999,name:'Special / Other',label:kind,key:'z999'};\n}\nfunction upgradePlanCalculate(currentId,currentLevel,targetId,targetLevel,includeFailures=false){\n  const list=upgradeStages(),ci=list.findIndex(s=>s.id===currentId),ti=list.findIndex(s=>s.id===targetId);\n  currentLevel=Math.max(0,Number(currentLevel)||0);targetLevel=Math.max(0,Number(targetLevel)||0);\n  if(ci<0||ti<0||ti<ci||(ci===ti&&targetLevel<currentLevel))return {valid:false,message:'Target must be at or after your current progression.'};\n  let goldBase=0n,goldScaled=0n,matsBase={},matsScaled={},steps=0,idx=ci,level=currentLevel,partial=false,post30Rows=0,failureSteps=0;\n  const addMaterial=(slug,qty,factor)=>{if(!slug)return;upgradeAddMat(matsBase,slug,qty);upgradeAddScaled(matsScaled,slug,qty,factor)};\n  const addCost=(x)=>{\n    const f=upgradeCostFactors(x,includeFailures);\n    const g=BigInt(x?.gold||0);goldBase+=g;goldScaled+=g*f.gold;\n    addMaterial(x?.fragment_slug,x?.fragments,f.materials);\n    Object.entries(x?.monster_materials||{}).forEach(([k,v])=>addMaterial(k,v,f.materials));\n    if(Array.isArray(x?.extra_materials))x.extra_materials.forEach(m=>addMaterial(m.slug,m.quantity,f.materials));\n    else Object.entries(x?.extra_materials||{}).forEach(([k,v])=>addMaterial(k,v,f.materials));\n    if(x?.unknown_monster_materials){partial=true;post30Rows++}\n    if(f.fail>0)failureSteps++;\n    steps++;\n  };\n  const addTransition=(from,to)=>{\n    if(from.tier&&from.tier<6){\n      const x=DATA.codex.tier_upgrades.find(v=>Number(v.from_tier)===from.tier);\n      if(!x)throw new Error('Missing tier transition '+from.id);\n      const f=upgradeCostFactors(x,includeFailures);\n      const g=BigInt(x.gold||0);goldBase+=g;goldScaled+=g*f.gold;\n      addMaterial(x.essence?.slug,x.essence?.quantity,f.materials);\n      Object.entries(x.monster_materials||{}).forEach(([k,v])=>addMaterial(k,v,f.materials));\n      if(f.fail>0)failureSteps++;\n    }else{\n      const rank=from.tier===6?1:to.rank,x=permTransition(rank);\n      if(!x)throw new Error('Missing Awaken transition A'+rank);\n      const f=upgradeCostFactors(x,includeFailures);\n      const g=BigInt(x.gold||0);goldBase+=g;goldScaled+=g*f.gold;\n      (x.materials||[]).forEach(m=>addMaterial(m.slug,m.quantity,f.materials));\n      if(f.fail>0)failureSteps++;\n    }\n    steps++;\n  };\n  try{\n    while(idx<ti){\n      const st=list[idx],rows=upgradeStageRows(st),max=upgradeStageMax(st);\n      while(level<max){\n        const row=rows.find(r=>Number(r.current)===level);\n        if(!row)return {valid:false,message:'Missing configured row for '+st.id+' +'+level+'.'};\n        addCost(row);level++;\n      }\n      addTransition(st,list[idx+1]);idx++;level=0;\n    }\n    const st=list[ti],rows=upgradeStageRows(st);\n    while(level<targetLevel){\n      const row=rows.find(r=>Number(r.current)===level);\n      if(!row)return {valid:false,message:'Missing configured row for '+st.id+' +'+level+'.'};\n      addCost(row);level++;\n    }\n  }catch(err){return {valid:false,message:String(err.message||err)}}\n  const mats={};\n  for(const [slug,scaled] of Object.entries(matsScaled))mats[slug]=includeFailures?upgradeScaledCeil(scaled):(matsBase[slug]||0n);\n  return {\n    valid:true,steps,partial,post30Rows,failureSteps,includeFailures,\n    goldBase,gold:includeFailures?upgradeScaledCeil(goldScaled):goldBase,\n    matsBase,mats\n  };\n}\nfunction upgradeSortedMaterials(result,sortMode){\n  let rows=Object.entries(result.mats).filter(([,q])=>q>0n).map(([slug,qty])=>({\n    slug,qty,base:result.matsBase[slug]||0n,biome:upgradeBiomeInfo(slug),name:upgradeMaterialName(slug)\n  }));\n  if(sortMode==='qty')rows.sort((a,b)=>a.qty===b.qty?a.name.localeCompare(b.name):(a.qty>b.qty?-1:1));\n  else if(sortMode==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));\n  else rows.sort((a,b)=>a.biome.key.localeCompare(b.biome.key)||a.name.localeCompare(b.name));\n  return rows;\n}\nfunction upgradePrefarmCostHtml(title,result,label,sortMode='biome'){\n  if(!result?.valid)return '<div class=\"category-card\"><h3>'+title+'</h3><div class=\"empty\">'+(result?.message||'No route available.')+'</div></div>';\n  const rows=upgradeSortedMaterials(result,sortMode);\n  let lastGroup='',cards='';\n  for(const row of rows){\n    if(sortMode==='biome'&&row.biome.key!==lastGroup){\n      lastGroup=row.biome.key;\n      cards+='<div class=\"upgrade-group-head\"><strong>'+row.biome.name+'</strong><span>'+(row.biome.tier===999?'Special / non-monster materials':'Biome T'+row.biome.tier)+'</span></div>';\n    }\n    const extra=result.includeFailures&&row.qty>row.base?row.qty-row.base:0n;\n    cards+='<div class=\"list-card upgrade-mat-card\">'+officialArt('items/materials/'+row.slug+'.webp','material:'+row.slug,36)+\n      '<div class=\"list-main\"><div class=\"list-title\">'+row.name+'</div><div class=\"list-meta\">'+row.biome.label+\n      (result.includeFailures?'<br>Base '+row.base.toLocaleString()+(extra>0n?' • reserve +'+extra.toLocaleString():''):'')+\n      '</div></div><strong>'+row.qty.toLocaleString()+'</strong></div>';\n  }\n  return '<div class=\"category-card\">'+\n    '<div class=\"row between wrap\"><div><h3>'+title+'</h3><p style=\"font-size:10px\">'+label+'</p></div><span class=\"pill '+(result.partial?'gold':'accent')+'\">'+result.steps+' step'+(result.steps===1?'':'s')+'</span></div>'+\n    '<div class=\"twocol\" style=\"margin-top:10px\">'+\n      '<div class=\"metric\"><small>'+(result.includeFailures?'Estimated Gold':'Gold')+'</small><strong class=\"gold\">'+result.gold.toLocaleString()+'</strong>'+(result.includeFailures?'<small>Base '+result.goldBase.toLocaleString()+'</small>':'')+'</div>'+\n      '<div class=\"metric\"><small>Material types</small><strong>'+rows.length+'</strong>'+(result.includeFailures?'<small>'+result.failureSteps+' failure-risk step'+(result.failureSteps===1?'':'s')+'</small>':'')+'</div>'+\n    '</div>'+\n    (result.includeFailures?'<div class=\"note upgrade-estimate-note\"><b>Failure-adjusted estimate:</b> Uses each step’s listed success chance and the 30% material refund on failed attempts. Gold is treated as spent each attempt. The game’s safety-net / pity behavior is not modeled yet, so high-failure upgrades can be overestimated.</div>':'')+\n    (result.partial?'<div class=\"note\" style=\"margin-top:8px\"><b>Post-A30 permanent progression:</b> ordinary monster-material quantities are not published for these enhancement rows, so Arcana still leaves those unguessed.</div>':'')+\n    (cards?'<div class=\"card-list upgrade-material-list\" style=\"margin-top:10px\">'+cards+'</div>':'<div class=\"note\" style=\"margin-top:10px\">No known materials required for this route.</div>')+\n  '</div>';\n}\nrenderData=function(){\n  state.upgrade=state.upgrade||{currentStage:'T1',currentLevel:0,targetStage:'T6',targetLevel:30};\n  const u=state.upgrade,stages=upgradeStages();\n  if(!stages.some(x=>x.id===u.currentStage))u.currentStage='T1';\n  if(!stages.some(x=>x.id===u.targetStage))u.targetStage='T6';\n  if(typeof u.includeFailures!=='boolean')u.includeFailures=false;\n  if(!['biome','qty','name'].includes(u.materialSort))u.materialSort='biome';\n  u.currentLevel=Math.min(Number(u.currentLevel)||0,upgradeStageMax(stages.find(x=>x.id===u.currentStage)));\n  u.targetLevel=Math.min(Number(u.targetLevel)||0,upgradeStageMax(stages.find(x=>x.id===u.targetStage)));\n  $('#dataPage').innerHTML=\n    '<div class=\"panel game glow\">'+\n      '<div class=\"row between wrap\"><div><h3>Item Upgrade Calculator</h3><p style=\"font-size:10px\">Plan one upgrade, a full Awakened rank, or everything from your current item to a future target.</p></div><span class=\"pill good\">T1 → A50</span></div>'+\n      '<div class=\"config-grid\" style=\"margin-top:12px\">'+\n        '<label>Current stage<select id=\"upCurrentStage\">'+upgradeStageOptions(u.currentStage)+'</select></label>'+\n        '<label>Current level<select id=\"upCurrentLevel\">'+upgradeLevelOptions(u.currentStage,u.currentLevel)+'</select></label>'+\n        '<label>Target stage<select id=\"upTargetStage\">'+upgradeStageOptions(u.targetStage)+'</select></label>'+\n        '<label>Target level<select id=\"upTargetLevel\">'+upgradeLevelOptions(u.targetStage,u.targetLevel)+'</select></label>'+\n      '</div>'+\n      '<div class=\"row wrap upgrade-actions\" style=\"margin-top:10px\">'+\n        '<button class=\"secondary\" id=\"upTargetNext\">Next upgrade</button>'+\n        '<button class=\"secondary\" id=\"upTargetNextRank\">Next tier / rank</button>'+\n        '<button class=\"secondary\" id=\"upTargetStageMax\">Target stage max</button>'+\n        '<button class=\"ghost\" id=\"upTargetA50\">Target A50 +30</button>'+\n      '</div>'+\n      '<div class=\"upgrade-prefarm-controls\">'+\n        '<label class=\"upgrade-check\"><input id=\"upIncludeFailures\" type=\"checkbox\" '+(u.includeFailures?'checked':'')+'><span><b>Include failed attempts</b><small>Estimate extra Gold and materials using success chance + 30% failed-material refund.</small></span></label>'+\n        '<label class=\"upgrade-sort\">Sort materials<select id=\"upMaterialSort\"><option value=\"biome\" '+(u.materialSort==='biome'?'selected':'')+'>Biome</option><option value=\"qty\" '+(u.materialSort==='qty'?'selected':'')+'>Quantity</option><option value=\"name\" '+(u.materialSort==='name'?'selected':'')+'>Name</option></select></label>'+\n      '</div>'+\n      '<div class=\"note\" style=\"margin-top:9px\">For example, set <b>A1 +0 → A2 +0</b> to see the entire cost of finishing A1 and ranking into A2. Failure estimates are statistical until the exact safety-net / pity sequence is confirmed.</div>'+\n    '</div>'+\n    '<div id=\"upNextResult\" class=\"panel\"></div>'+\n    '<div id=\"upTargetResult\" class=\"panel\"></div>'+\n    '<div class=\"panel\"><div class=\"row between wrap\"><div><h3>Related tools</h3><p style=\"font-size:10px\">Item details, Drop Bonuses and gear comparison stay in the Codex.</p></div><button class=\"secondary\" data-route=\"codex\">Open Gear Codex</button></div></div>';\n  const refresh=(stageEl,levelEl)=>{const st=upgradeStages().find(x=>x.id===stageEl.value),v=Math.min(Number(levelEl.value)||0,upgradeStageMax(st));levelEl.innerHTML=upgradeLevelOptions(stageEl.value,v)};\n  const sync=()=>{\n    u.currentStage=$('#upCurrentStage').value;u.currentLevel=Number($('#upCurrentLevel').value)||0;\n    u.targetStage=$('#upTargetStage').value;u.targetLevel=Number($('#upTargetLevel').value)||0;\n    u.includeFailures=!!$('#upIncludeFailures').checked;u.materialSort=$('#upMaterialSort').value;save();\n    const n=nextItemUpgrade(u.currentStage,u.currentLevel);\n    $('#upNextResult').innerHTML=n?upgradePrefarmCostHtml('Next upgrade',upgradePlanCalculate(u.currentStage,u.currentLevel,n.stageId,n.level,u.includeFailures),u.currentStage+' +'+u.currentLevel+' → '+n.label,u.materialSort):'<div class=\"category-card\"><h3>Tracking limit reached</h3><div class=\"empty\">A50 +30 is Arcana’s current display limit, not a confirmed game cap.</div></div>';\n    $('#upTargetResult').innerHTML=upgradePrefarmCostHtml('Target total',upgradePlanCalculate(u.currentStage,u.currentLevel,u.targetStage,u.targetLevel,u.includeFailures),u.currentStage+' +'+u.currentLevel+' → '+u.targetStage+' +'+u.targetLevel,u.materialSort);\n  };\n  $('#upCurrentStage').onchange=()=>{refresh($('#upCurrentStage'),$('#upCurrentLevel'));sync()};\n  $('#upCurrentLevel').onchange=sync;\n  $('#upTargetStage').onchange=()=>{refresh($('#upTargetStage'),$('#upTargetLevel'));sync()};\n  $('#upTargetLevel').onchange=sync;\n  $('#upIncludeFailures').onchange=sync;\n  $('#upMaterialSort').onchange=sync;\n  $('#upTargetNext').onclick=()=>{const n=nextItemUpgrade($('#upCurrentStage').value,Number($('#upCurrentLevel').value)||0);if(!n)return;$('#upTargetStage').value=n.stageId;refresh($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value=String(n.level);sync()};\n  $('#upTargetNextRank').onclick=()=>{const list=upgradeStages(),i=list.findIndex(x=>x.id===$('#upCurrentStage').value);if(i<0||i>=list.length-1)return;$('#upTargetStage').value=list[i+1].id;refresh($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value='0';sync()};\n  $('#upTargetStageMax').onclick=()=>{const st=upgradeStages().find(x=>x.id===$('#upTargetStage').value);$('#upTargetLevel').value=String(upgradeStageMax(st));sync()};\n  $('#upTargetA50').onclick=()=>{$('#upTargetStage').value='A50';refresh($('#upTargetStage'),$('#upTargetLevel'));$('#upTargetLevel').value='30';sync()};\n  sync();\n};\n";
// ARCANA_UPGRADE_PREFARM_END
// ARCANA_UPGRADE_PREFARM_CSS_BEGIN
const UPGRADE_PREFARM_CSS="\n.upgrade-prefarm-controls{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(180px,.7fr);gap:8px;margin-top:10px}\n.upgrade-check{display:flex!important;align-items:center;gap:9px;padding:9px 10px;border:1px solid rgba(192,132,252,.18);border-radius:12px;background:rgba(168,85,247,.045);cursor:pointer}\n.upgrade-check input{width:18px!important;height:18px!important;min-height:0!important;flex:0 0 auto;accent-color:#A855F7}\n.upgrade-check span{display:block;min-width:0}\n.upgrade-check b{display:block;font-size:10px}\n.upgrade-check small{display:block;font-size:8px;line-height:1.35;margin-top:2px;color:var(--muted)}\n.upgrade-sort{padding:8px 9px;border:1px solid rgba(192,132,252,.18);border-radius:12px;background:rgba(168,85,247,.035)}\n.upgrade-sort select{margin-top:4px}\n.upgrade-estimate-note{margin-top:8px!important}\n.upgrade-material-list .upgrade-group-head{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 9px;border-radius:10px;background:rgba(168,85,247,.075);border:1px solid rgba(192,132,252,.14)}\n.upgrade-group-head strong{font-size:10px}\n.upgrade-group-head span{font-size:8px;color:var(--muted)}\n.upgrade-mat-card .list-meta{line-height:1.35!important}\n.metric>small:last-child{display:block;margin-top:3px;color:var(--muted)}\n@media(max-width:759px){\n .upgrade-prefarm-controls{grid-template-columns:1fr}\n #dataPage .upgrade-actions{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important}\n #dataPage .upgrade-actions button{width:100%;min-height:38px}\n .upgrade-check{padding:9px}\n .upgrade-material-list .upgrade-group-head{padding:6px 8px}\n}\n";
