const PET_COMPOUND_FIX_V1="\nconst arcanaCompoundStepCeil=(value,multiplier)=>Math.ceil((Number(value)*Number(multiplier))-1e-9);\ncompoundValue=function(r,b,l){\n  const R=HATCH[r],base=R?.bonuses?.[b];\n  if(base==null)return null;\n  const suffix=PF.has(b)?'':'%',n=Math.max(0,+l||0),e=R.cap==null?n:Math.min(n,R.cap);\n  let v=base,f='';\n  if(r!=='legendary'){\n    for(let i=1;i<=e;i++)v+=Math.max(1,Math.ceil(base*R.additive-1e-9));\n  }else if(L3.includes(' '+b+' ')){\n    for(let i=1;i<=e;i++)v=arcanaCompoundStepCeil(v,i<=10?1.2:i<=30?1.1:1.07);\n    f='3';\n  }else if(L2.includes(' '+b+' ')){\n    for(let i=1;i<=e;i++)v=arcanaCompoundStepCeil(v,i<=10?1.2:1.1);\n    f='2';\n  }else if(b==='defense'){\n    for(let i=1;i<=Math.min(e,10);i++)v=arcanaCompoundStepCeil(v,1.2);\n    if(e>10)v+=2*(e-10);\n    f='d';\n  }else if(b.startsWith('increased_')){\n    v=base+3*e;f='p';\n  }else if(b==='all_class_skills'){\n    v=base+e;f='a';\n  }\n  return{base,suffix,value:v,e,n,f,c:e!==n};\n};\nconst __arcanaRenderPetsRounded=renderPets;\nrenderPets=function(){\n  __arcanaRenderPetsRounded();\n  const p=state.pets,x=compoundValue(p.rarity,p.bonus,p.level);\n  if(!x)return;\n  const exact=$('#petCompoundResult .arcana-pet-exact');if(exact)exact.remove();\n  [...document.querySelectorAll('#petCompoundResult .compound-step em')].forEach(el=>el.remove());\n  const note=$('#petCompoundResult .arcana-rounding-note');\n  if(note)note.textContent=p.rarity==='legendary'\n    ?'Game calculation: each multiplicative Compound step rounds up before the next Compound level is applied.'\n    :'Each Compound level rounds its gain up, with at least +1 per level.';\n};";
// ARCANA_PET_COMPOUND_FIX_V1_END


