const ARCANA_ZANE_SIGNATURE_MARKUP="<div class=\"arcana-signature\" id=\"arcanaSignature\" aria-label=\"Made by Zane, leader of PDX and OVK, for the IdleArc community\">\n<button class=\"arcana-signature-close\" id=\"arcanaSignatureClose\" type=\"button\" aria-label=\"Hide creator credit\" title=\"Hide\">×</button>\n<div class=\"arcana-signature-mark\" aria-hidden=\"true\"><img src=\"data:image/webp;base64,\" alt=\"\"></div>\n<div class=\"arcana-signature-main\">\n<div class=\"arcana-signature-heading\"><span class=\"arcana-signature-kicker\">Made by</span><strong>Zane</strong><span class=\"arcana-signature-sigil\">✦</span><span class=\"arcana-signature-role\">Leader of PDX &amp; OVK</span></div>\n<p>Arcana is built for the <b>IdleArc community</b>, and the project gets better through your suggestions, ideas, and feedback.</p>\n</div>\n<div class=\"arcana-signature-stars\" aria-hidden=\"true\">✦ · ✧ · ✦</div>\n</div>";
const ARCANA_ZANE_SIGNATURE_CSS=".arcana-signature{position:relative;display:grid;grid-template-columns:84px minmax(0,1fr);align-items:center;gap:18px;padding:18px 44px 18px 18px;border-radius:20px;overflow:hidden;background:radial-gradient(260px 120px at 10% 55%,rgba(168,85,247,.16),transparent 72%),radial-gradient(340px 150px at 90% 50%,rgba(126,34,206,.08),transparent 75%),linear-gradient(100deg,rgba(28,16,48,.94),rgba(12,8,22,.92));border:1px solid rgba(192,132,252,.32);box-shadow:0 12px 30px rgba(0,0,0,.2),inset 0 1px 0 rgba(255,255,255,.03)}\n.arcana-signature:before,.arcana-signature:after{content:\"\";position:absolute;border:1px solid rgba(192,132,252,.08);border-radius:50%;pointer-events:none}.arcana-signature:before{width:260px;height:180px;left:-120px;top:-110px}.arcana-signature:after{width:300px;height:210px;right:-160px;bottom:-150px}\n.arcana-signature-mark{position:relative;z-index:1;width:84px;height:84px;display:grid;place-items:center;border-radius:20px;background:linear-gradient(145deg,rgba(168,85,247,.19),rgba(46,22,80,.18));border:1px solid rgba(192,132,252,.3);box-shadow:0 0 24px rgba(168,85,247,.12),inset 0 1px 0 rgba(255,255,255,.04)}\n.arcana-signature-mark img{width:74px;height:74px;object-fit:contain;display:block;filter:drop-shadow(0 0 10px rgba(168,85,247,.45))}\n.arcana-signature-main{text-align:center;min-width:0;position:relative;z-index:1}.arcana-signature-heading{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.arcana-signature-kicker{font-size:8px;text-transform:uppercase;letter-spacing:.28em;font-weight:800;color:#A995BA}.arcana-signature-heading strong{font-family:Georgia,'Times New Roman',serif;font-size:30px;font-style:italic;font-weight:500;color:#F3E8FF;text-shadow:0 0 18px rgba(192,132,252,.22)}.arcana-signature-sigil{font-size:16px;color:#C084FC}.arcana-signature-role{font-family:Georgia,'Times New Roman',serif;font-size:10px;letter-spacing:.16em;color:#BAA8C8}.arcana-signature-main p{margin:8px auto 0;max-width:760px;font-size:10px;line-height:1.5;color:#B3A5C2}.arcana-signature-main p b{color:#E0CFF0}\n.arcana-signature-close{position:absolute;top:8px;right:10px;z-index:4;width:20px;height:20px;min-height:0!important;padding:0!important;border:0!important;background:transparent!important;color:rgba(220,205,238,.32)!important;font-size:14px;box-shadow:none!important;cursor:pointer}.arcana-signature-close:hover{color:rgba(244,232,255,.8)!important}.arcana-signature-stars{position:absolute;left:22px;bottom:7px;font-size:7px;letter-spacing:9px;color:rgba(192,132,252,.32)}\n.arcana-signature[hidden]{display:none!important}\n@media(max-width:600px){.arcana-signature{grid-template-columns:64px minmax(0,1fr);gap:11px;padding:12px 28px 12px 12px;border-radius:16px}.arcana-signature-mark{width:64px;height:64px;border-radius:15px}.arcana-signature-mark img{width:56px;height:56px}.arcana-signature-heading{gap:6px}.arcana-signature-kicker{font-size:6px;letter-spacing:.2em}.arcana-signature-heading strong{font-size:22px}.arcana-signature-role{font-size:7px;letter-spacing:.1em}.arcana-signature-main p{font-size:7.5px;line-height:1.4;margin-top:5px}.arcana-signature-stars{left:14px;bottom:4px}.arcana-signature-close{top:5px;right:6px}}\n@media(max-width:390px){.arcana-signature{grid-template-columns:56px minmax(0,1fr)}.arcana-signature-mark{width:56px;height:56px}.arcana-signature-mark img{width:49px;height:49px}.arcana-signature-role{flex-basis:100%}.arcana-signature-main p{font-size:7px}}";
const ARCANA_ZANE_SIGNATURE_CLIENT="const __arcanaRenderHomeSignatureBase=renderHome;renderHome=function(){__arcanaRenderHomeSignatureBase();const sig=$('#arcanaSignature'),close=$('#arcanaSignatureClose');const hidden=localStorage.getItem('arcana_signature_hidden')==='1';if(sig)sig.hidden=hidden;if(close&&sig)close.onclick=(ev)=>{ev.preventDefault();ev.stopPropagation();sig.hidden=true;localStorage.setItem('arcana_signature_hidden','1')}};";
