 try{
  const upstream=await fetch(V3_ORIGIN+u.pathname+u.search,{headers:{Accept:c.req.header('accept')||'*/*'},signal:AbortSignal.timeout(18000)});
  if(!upstream.ok&&upstream.status>=500)throw new Error('V3 upstream HTTP '+upstream.status);
  if(u.pathname==='/'||u.pathname==='/index.html'){
   let h=await upstream.text();
   h=h.replace('<meta name="robots" content="noindex,nofollow">','<meta name="robots" content="index,follow">');
   h=h.replace('</head>','<link rel="canonical" href="https://arcanacompanion.xyz/"></head>');
   return c.html(h,upstream.status,{"Cache-Control":"no-store","X-Arcana-Version":"v3-production"});
  }
  const h=new Headers(upstream.headers);for(const key of ['content-encoding','content-length','transfer-encoding','x-robots-tag'])h.delete(key);
  h.set('X-Arcana-Version','v3-production');if(u.pathname.startsWith('/src/')||u.pathname==='/styles.css')h.set('cache-control','no-store');
  return new Response(upstream.body,{status:upstream.status,headers:h});
 }catch(e){console.error('ARCANA_V3_PUBLIC_PROXY_ERROR',u.pathname,String(e));if(u.pathname==='/'||u.pathname==='/index.html')return c.html(arcanaAttachDesign(withSharedLfgPortal(htmlFixed())),200,{"Cache-Control":"no-store","X-Arcana-Version":"legacy-fallback"});return c.text('Arcana V3 temporarily unavailable',502,{"Cache-Control":"no-store"});}
